public class BackoffDemo {
    static long backoffDelay(int attempt) {
        return (long)(100 * Math.pow(2, attempt));
    }
    public static void main(String[] args) {
        for (int i = 0; i < 4; i++) {
            System.out.println("Attempt " + i + ": " + backoffDelay(i) + "ms");
        }
    }
}

import java.util.HashMap;
import java.util.Map;

public class CacheDemo {
    static Map<Integer, String> cache = new HashMap<>();
    static String getProduct(int id) {
        if (cache.containsKey(id)) {
            System.out.println("Cache hit: " + cache.get(id));
            return cache.get(id);
        }
        String loaded = "Product-" + id;
        System.out.println("Cache miss, loading: " + id);
        cache.put(id, loaded);
        return loaded;
    }
    public static void main(String[] args) {
        getProduct(1);
        getProduct(1);
        getProduct(2);
    }
}

public class ShardingDemo {
    static int getShard(int userId, int numShards) {
        return userId % numShards;
    }
    public static void main(String[] args) {
        int numShards = 3;
        for (int userId = 0; userId < 5; userId++) {
            System.out.println("User " + userId + " -> Shard " + getShard(userId, numShards));
        }
    }
}

public class EventSourcingDemo {
    public static void main(String[] args) {
        String[] events = {"DEPOSIT:100", "DEPOSIT:50", "WITHDRAW:30"};
        int balance = 0;
        for (String event : events) {
            String[] parts = event.split(":");
            int amount = Integer.parseInt(parts[1]);
            if (parts[0].equals("DEPOSIT")) balance += amount;
            else if (parts[0].equals("WITHDRAW")) balance -= amount;
        }
        System.out.println("Final balance: " + balance);
    }
}
